class Solution { fun minSubarray(nums:IntArray,p:Int):Int{val remainder=(nums.sumOf{it.toLong()}%p).toInt();if(remainder==0)return 0;val latest=mutableMapOf(0 to -1);var prefix=0;var answer=nums.size;for(i in nums.indices){prefix=((prefix.toLong()+nums[i])%p).toInt();val needed=(prefix-remainder+p)%p;latest[needed]?.let{answer=minOf(answer,i-it)};latest[prefix]=i};return if(answer==nums.size)-1 else answer} }
